# 1) Очистка БД от прошлых записей (features, tasks, graph_runs, agent_events и пр.)
DB=/opt/feature-factory/data/test.db
if [ -f "$DB" ]; then
  sqlite3 "$DB" <<'SQL'
PRAGMA foreign_keys=OFF;
DELETE FROM tasks;
DELETE FROM graph_runs;
DELETE FROM features;
DELETE FROM agent_events;
DELETE FROM change_log;
DELETE FROM code_registry;
DELETE FROM symbol_index;
DELETE FROM call_graph_edges;
VACUUM;
SQL
fi
# 2) Удалим возможный ранее применённый файл роутера
rm -f app/api/ping.py
# 3) Прочитаем intent и подготовим payload
python3 - << 'PY' 2>/dev/null || .venv/bin/python - << 'PY'
import json, sys
with open('intent.json','r',encoding='utf-8') as f:
    intent = json.load(f)
payload = {"title": intent.get("title","MVP-SMOKE-TEST-01"), "intent": intent}
print(json.dumps(payload, ensure_ascii=False))
PY"], "timeout": 120000}

